const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-125.410394, -41.729403]);
  const aoi = point.buffer(100000); // 100km radius

  const startDate1 = '2019-11-01';
  const endDate1 = '2020-02-29'; // 2020 is a leap year

  const startDate2 = '2018-11-01';
  const endDate2 = '2019-02-28';

  const collectionId = 'NASA/OCEANDATA/MODIS-Aqua/L3SMI';
  const band = 'chlor_a';

  // 2. Data Acquisition & Initial Check
  const collection1 = ee.ImageCollection(collectionId)
    .filterDate(startDate1, endDate1)
    .filterBounds(aoi)
    .select(band);

  const collection2 = ee.ImageCollection(collectionId)
    .filterDate(startDate2, endDate2)
    .filterBounds(aoi)
    .select(band);

  const size1 = collection1.size().getInfo();
  const size2 = collection2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    console.log(`Image count 2019-2020: ${size1}`);
    console.log(`Image count 2018-2019: ${size2}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Image count 2019-2020: ${size1}`);
  console.log(`Image count 2018-2019: ${size2}`);

  // 3. Processing
  const image1 = collection1.mean();
  const image2 = collection2.mean();

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 4000, // Use a coarse scale for large area oceanography
    maxPixels: 1e9
  });

  const stats2 = image2.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 4000,
    maxPixels: 1e9
  });

  const mean1 = stats1.get(band + '_mean').getInfo();
  const count1 = stats1.get(band + '_count').getInfo();

  const mean2 = stats2.get(band + '_mean').getInfo();
  const count2 = stats2.get(band + '_count').getInfo();

  // 4. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels 2019-2020: ${count1}`);
    console.log(`Valid pixels 2018-2019: ${count2}`);
    console.log("No valid pixels found after processing.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels 2019-2020: ${count1}`);
  console.log(`Valid pixels 2018-2019: ${count2}`);

  if (mean1 === null || mean2 === null) {
    console.log("Calculation resulted in null.");
    console.log("C3");
    return;
  }

  console.log(`Mean Chlorophyll 2019-2020 (mg/m^3): ${mean1.toFixed(4)}`);
  console.log(`Mean Chlorophyll 2018-2019 (mg/m^3): ${mean2.toFixed(4)}`);

  if (mean1 > mean2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(err => {
    console.error("An error occurred:", err);
    console.log("D");
});
